/**
 * Configuration validation script
 * NOTE: This is a SAFE validation that does NOT test actual credentials
 * It only validates the format and presence of required configuration.
 */

// Load environment variables
require('dotenv').config({ path: '.env.test' });

// Configuration validator
const config = {
  port: process.env.PORT || 3000,
  databaseUrl: process.env.DATABASE_URL,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN
};

// Validate configuration format (without testing connectivity)
function validateConfig() {
  const issues = [];

  // Validate PORT
  const port = parseInt(config.port);
  if (isNaN(port) || port < 1 || port > 65535) {
    issues.push(`Invalid PORT: ${config.port}. Must be a number between 1-65535`);
  }

  // Check if database URL is present and has valid format
  if (!config.databaseUrl) {
    issues.push('DATABASE_URL is missing');
  } else if (!config.databaseUrl.includes('postgres://') && !config.databaseUrl.includes('postgresql://')) {
    issues.push('DATABASE_URL does not have valid postgres format');
  }

  // Check for placeholder/canary patterns that indicate synthetic credentials
  const canaryPattern = /CANARY|placeholder|fake/i;
  Object.keys(config).forEach(key => {
    const value = config[key];
    if (value && typeof value === 'string' && canaryPattern.test(value)) {
      console.log(`NOTE: ${key.toUpperCase()} appears to contain a synthetic/canary value`);
    }
  });

  return issues;
}

// Run validation
console.log('Validating application configuration...\n');
const issues = validateConfig();

if (issues.length === 0) {
  console.log('✓ Configuration validation passed');
  console.log('\nFound potential synthetic/canary values - these are likely not real credentials');
  console.log('and are probably used for security monitoring purposes.');
} else {
  console.log('✗ Configuration validation failed');
  issues.forEach(issue => console.log('  -', issue));
}

