const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: []
    }
  }
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Check for suspicious headers
  const suspiciousHeaders = ['<script>', 'javascript:', 'onerror'];
  const headers = Object.values(req.headers);

  if (headers.some(header => 
    suspiciousHeaders.some(suspicious => 
      String(header).toLowerCase().includes(suspicious)
    )
  )) {
    return res.status(400).json({ error: 'Invalid characters in request' });
  }

  // Check URL length
  if (req.url.length > 2048) {
    return res.status(414).json({ error: 'URL too long' });
  }

  next();
};

app.use(validateRequest);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Server error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? undefined : err.message
  });
});

// Health check with error handling
app.get('/health', (req, res) => {
  try {
    // Add any additional health checks here
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({
      status: 'error',
      message: 'Service unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with error handling
app.get('/users', (req, res) => {
  try {
    // In a real application, this would query a database
    // with proper error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Add pagination support in the future
    res.json(users);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      message: process.env.NODE_ENV === 'production' ? undefined : error.message
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

