/**
 * Configuration validator - checks for required environment variables
 * without making actual connections to external services.
 * 
 * This is a safe alternative to testing actual credentials,
 * especially when canary values are present.
 */

function validateConfig() {
  const requiredVars = [
    'PORT',
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY'
    // Add other required env vars
  ];

  const missing = [];
  const found = [];

  requiredVars.forEach(varName => {
    if (!process.env[varName]) {
      missing.push(varName);
    } else {
      // If variable exists, check if it's not a canary/test value
      const value = process.env[varName];
      if (value.includes('CANARY') || value.includes('test') || value.includes('example')) {
        console.warn(`⚠️  Environment variable ${varName} contains suspicious value - may be a test/canary credential`);
      } else {
        found.push(varName);
      }
    }
  });

  if (missing.length > 0) {
    console.error(`❌ Missing required environment variables: ${missing.join(', ')}`);
    return false;
  }

  if (found.length > 0) {
    console.log(`✅ Configuration valid. Found ${found.length} production-ready credentials.`);
  }

  console.log(`ℹ️  ${missing.length} variables missing, ${found.length} valid, ${missing.length + found.length - missing.length} potentially test-related`);
  return true;
}

// Run validation if file is executed directly
if (require.main === module) {
  const isValid = validateConfig();
  process.exit(isValid ? 0 : 1);
}

module.exports = { validateConfig };

