    logger.error('Health check failed:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with potential future filtering (showing validation pattern)
app.get('/users', (req, res) => {
  try {
    // Example of query parameter validation
    const { limit, sort } = req.query;

    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate and apply limit if provided
    if (limit) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        logger.warn(`Invalid limit parameter: ${limit} from ${req.ip}`);
        return res.status(400).json({ 
          error: 'Invalid limit parameter. Must be a positive integer between 1 and 100.' 
        });
      }
      users = users.slice(0, limitNum);
    }

    // Future sorting capability (validation in place)
    if (sort) {
      if (!['name', 'id', 'email'].includes(sort)) {
        logger.warn(`Invalid sort parameter: ${sort} from ${req.ip}`);
        return res.status(400).json({ 
          error: 'Invalid sort parameter. Allowed values: name, id, email' 
        });
      }
      users.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    logger.info(`Users endpoint accessed with limit: ${limit}, sort: ${sort} from ${req.ip}`);
    res.json(users);

  } catch (error) {
