const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // Note: CSP can break some functionality, enable carefully
}));

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : true // Allow all in development
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false
});

// Apply rate limit to all routes
app.use(limiter);

// Parse JSON with size limit to prevent abuse
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Health check with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // This is unlikely to fail, but good practice
    res.status(500).json({
      error: 'Health check failed',
      code: 'HEALTH_CHECK_FAILED'
    });
  }
});

// Users route with input validation
app.get('/users', 
  // Validate query parameters
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        code: 'VALIDATION_ERROR',
        details: errors.array()
      });
    }

    try {
      // Extract and sanitize query parameters
      const limit = parseInt(req.query.limit) || 10;
      const page = parseInt(req.query.page) || 1;

      // In a real app, this data would come from a database with proper filtering
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Simple pagination (in real app, this would be handled by the database)
      const startIndex = (page - 1) * limit;
      const paginatedUsers = mockUsers.slice(startIndex, startIndex + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: mockUsers.length,
          pages: Math.ceil(mockUsers.length / limit)
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        error: 'Internal server error',
        code: 'INTERNAL_ERROR'
      });
    }
  }
);

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    code: 'NOT_FOUND'
  });
});

// Global error handler (should be after all routes)
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Determine status code based on error type
  const statusCode = error.statusCode || error.status || 500;

  // Don't expose sensitive error details in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message,
    code: error.code || 'INTERNAL_SERVER_ERROR'
  };

  // Add validation errors if present
  if (error.name === 'ValidationError' && !process.env.NODE_ENV === 'production') {
    errorResponse.details = error.details;
  }

  res.status(statusCode).json(errorResponse);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

