  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent caching of sensitive data
  res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  next();
});

// Simple rate limiting without express-rate-limit package
const requestCounts = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean old entries
  for (const [requestIp, requestTime] of requestCounts) {
    if (now - requestTime > WINDOW_MS) {
      requestCounts.delete(requestIp);
    }
  }

  // Check rate limit
  if (requestCounts.has(ip)) {
    const count = requestCounts.get(ip);
    if (count >= MAX_REQUESTS) {
      return res.status(429).json({
        status: 'error',
        message: 'Too many requests from this IP, please try again later.'
      });
    }
    requestCounts.set(ip, count + 1);
  } else {
    requestCounts.set(ip, 1);
  }

  next();
});

