const https = require('https');
const url = require('url');
const { URL } = url;
const fs = require('fs');
const path = require('path');

// Extract credentials from .env.test file
function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    // Parse each line, skipping comments and empty lines
    content.split('\n').forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const equalsIndex = line.indexOf('=');
        if (equalsIndex > 0) {
          const key = line.substring(0, equalsIndex).trim();
          const value = line.substring(equalsIndex + 1).trim();
          env[key] = value;
        }
      }
    });

    return env;
  } catch (error) {
    console.log(`❌ Failed to read ${filePath}: ${error.message}`);
    return {};
  }
}

// Simple masker for sensitive credentials
function maskCredential(cred) {
  if (!cred) return 'undefined';
  if (cred.length <= 4) return '*'.repeat(cred.length);

  // For structured credentials like 'prefix-xxxx-yyyy-zzzz'
  if (cred.includes('-')) {
    return cred.split('-').map((part, i) => 
      i === 0 ? part : part.replace(/./g, '*')
    ).join('-');
  }

  // For other formats, show first 4 and last 4 chars
  return cred.substring(0, 4) + '*'.repeat(Math.max(0, cred.length - 8)) + 
         (cred.length > 8 ? cred.substring(cred.length - 4) : '');
}

// Create a simple HTTP request wrapper
function makeRequest(options, postData = null) {
  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        resolve({
          success: res.statusCode >= 200 && res.statusCode < 300,
          statusCode: res.statusCode,
          data: data,
          headers: res.headers
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        success: false,
        error: error.message
      });
    });

    if (postData) {
      req.write(postData);
    }

    req.setTimeout(10000, () => {
      req.destroy();
      resolve({
        success: false,
        error: 'Request timeout'
      });
    });

    req.end();
  });
}

