// Security middleware - manual implementation without helmet
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size to prevent abuse
  if (req.headers['content-length'] && parseInt(req.headers['content-length']) > 1048576) {
    return res.status(413).json({
      error: 'Payload too large',
      message: 'Request body cannot exceed 1MB'
    });
  }

  next();
});

// Simplified rate limiting (basic in-memory)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const MAX_REQUESTS = 100; // per window

app.use((req, res, next) => {
  const clientIP = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
  const now = Date.now();

  // Clean up old entries
  if (requestCounts.size > 1000) {
    for (const [key, value] of requestCounts) {
      if (now - value.timestamp > RATE_LIMIT_WINDOW) {
        requestCounts.delete(key);
      }
    }
  }

  const clientData = requestCounts.get(clientIP) || { count: 0, timestamp: now };

  // Reset counter if outside window
  if (now - clientData.timestamp > RATE_LIMIT_WINDOW) {
    clientData.count = 0;
    clientData.timestamp = now;
  }

  clientData.count++;
  requestCounts.set(clientIP, clientData);

  if (clientData.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.'
    });
  }

  next();
});

// Enhanced logging middleware
