const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Body parser with limits
app.use(express.json({
  limit: '10kb'  // Prevent large payload attacks
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests
app.use(limiter);

// Health check with error handling
app.get('/health', [
  // Input validation (though minimal for health check)
  (req, res, next) => {
    try {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      });
    } catch (error) {
      console.error('Health check error:', error);
      res.status(503).json({
        status: 'error',
        message: 'Service unavailable'
      });
    }
  }
]);

// Users endpoint with proper error handling
app.get('/users', [
  // Input validation for query parameters if needed
  (req, res, next) => {
    try {
      // Validate and sanitize query parameters
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;

      // Basic validation
      if (page < 1 || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Invalid parameters',
          message: 'Page and limit must be positive numbers. Limit cannot exceed 100.'
        });
      }

      // Mock data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Simple pagination
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;

      res.json({
        users: users.slice(startIndex, endIndex),
        currentPage: page,
        totalPages: Math.ceil(users.length / limit),
        totalUsers: users.length
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({
        error: 'internal_server_error',
        message: 'An unexpected error occurred'
      });
    }
  }
]);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'not_found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Determine status code based on error type
  const statusCode = error.statusCode || 500;

  // Don't expose internal details in production
  const response = {
    error: 'internal_server_error',
    message: 'An unexpected error occurred'
  };

  // Only include error details in development
  if (process.env.NODE_ENV === 'development') {
    response.details = error.message;
    response.stack = error.stack;
  }

  res.status(statusCode).json(response);
});

// Graceful shutdown
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;

