const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.hidePoweredBy());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

app.use(limiter);

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*'
}));

// Parse JSON with size limit to prevent abuse
app.use(express.json({
  limit: '10kb'
}));

// Input validation helper
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (id !== undefined) {
    const parsedId = parseInt(id, 10);
    if (isNaN(parsedId) || parsedId <= 0) {
      return res.status(400).json({
        error: 'Invalid ID parameter',
        message: 'ID must be a positive integer'
      });
    }
    req.params.id = parsedId; // Use the parsed integer
  }
  next();
};

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Health check failed'
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', async (req, res) => {
  try {
    // Simulated data access with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Check for query parameters that might affect response
    const includeSensitive = req.query.include_sensitive?.toLowerCase() === 'true';

    if (includeSensitive) {
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Insufficient permissions to access sensitive data'
      });
    }

    res.json(users);

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.originalUrl} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Distinguish between operational and programmer errors
  if (error instanceof SyntaxError && error.status === 400 && 'body' in error) {
    return res.status(400).json({
      error: 'Bad request',
      message: 'Invalid JSON in request body'
    });
  }

  const status = error.status || 500;
  const message = status === 500 ? 'Internal server error' : error.message;

  res.status(status).json({
    error: status === 500 ? 'Internal server error' : 'Error',
    message
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

