const express = require('express');
const app = express();

// Security middleware - limit request size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security: Set security headers manually
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent caching of responses
  res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  next();
});

// Input validation middleware for query parameters
const validateQueryParams = (req, res, next) => {
  try {
    // Check for potentially dangerous characters in query parameters
    const queryParams = Object.values(req.query);
    const dangerousPatterns = [/<script/i, /javascript:/i, /on\w+=/i, /<iframe/i, /<img/i];

    for (const param of queryParams) {
      if (typeof param === 'string') {
        for (const pattern of dangerousPatterns) {
          if (pattern.test(param)) {
            return res.status(400).json({
              error: 'Invalid input parameters',
              message: 'Potential XSS attempt detected'
            });
          }
        }
      }
    }

    // If we get here, validation passed
    next();
  } catch (error) {
    console.error('Validation error:', error);
    res.status(400).json({
      error: 'Validation failed',
      message: 'There was an error processing your request'
    });
  }
};

// Use validation middleware for all routes
app.use(validateQueryParams);

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Additional input validation for this specific endpoint
    if (req.query && Object.keys(req.query).length > 5) {
      return res.status(400).json({
        error: 'Too many parameters',
        message: 'Maximum 5 query parameters allowed'
      });
    }

    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Validate query parameters for users endpoint
    if (req.query.id) {
      const id = parseInt(req.query.id);
      if (isNaN(id) || id <= 0) {
        return res.status(400).json({
          error: 'Invalid user ID',
          message: 'User ID must be a positive number'
        });
      }
    }

    // In a real application, this data would come from a database
    // with proper input sanitization
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users by ID if specified
    if (req.query.id) {
      const id = parseInt(req.query.id);
      const user = users.find(u => u.id === id);
      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `User with ID ${id} not found`
        });
      }
      return res.json([user]);
    }

    res.json(users);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred while retrieving users'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `The route ${req.method} ${req.url} does not exist`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'SyntaxError' && error.status === 400) {
    return res.status(400).json({
      error: 'Bad request',
      message: 'Invalid JSON in request body'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;

